CREATE TABLE public.user_permission_override (
  user_permission_override_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id u64 NOT NULL,
  permission_id u32 NOT NULL,
  permission_effect text NOT NULL,
  scope_type text NOT NULL DEFAULT 'GLOBAL'::text,
  scope_entity_id u64,
  normalized_scope_entity_id u64 GENERATED ALWAYS AS (
CASE
    WHEN (scope_type = ANY (ARRAY['GLOBAL'::text, 'SELF'::text])) THEN (0)::bigint
    ELSE COALESCE((scope_entity_id)::bigint, (0)::bigint)
END) STORED,
  valid_from timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  valid_to timestamp with time zone,
  granted_by_user_id u64,
  justification character varying(500) NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_user_permission_override_dates CHECK (valid_to IS NULL OR valid_to > valid_from),
  CONSTRAINT chk_user_permission_override_scope CHECK ((scope_type = ANY (ARRAY['GLOBAL'::text, 'SELF'::text])) AND scope_entity_id IS NULL OR (scope_type = ANY (ARRAY['INSTITUTION'::text, 'CAMPUS'::text, 'DEPARTMENT'::text, 'PROGRAMME'::text])) AND scope_entity_id IS NOT NULL),
  CONSTRAINT enum_permission_effect CHECK (permission_effect = ANY (ARRAY['ALLOW'::text, 'DENY'::text])),
  CONSTRAINT enum_scope_type CHECK (scope_type = ANY (ARRAY['GLOBAL'::text, 'INSTITUTION'::text, 'CAMPUS'::text, 'DEPARTMENT'::text, 'PROGRAMME'::text, 'SELF'::text])),
  CONSTRAINT uq_user_permission_override UNIQUE (user_id, permission_id, scope_type, normalized_scope_entity_id, valid_from),
  CONSTRAINT user_permission_override_pkey PRIMARY KEY (user_permission_override_id)
);
