  student_id bigint NOT NULL,
  academic_term_id bigint,
  planned_date date,
  detail text,
  request_status text NOT NULL DEFAULT 'SUBMITTED'::text,
  decision_remarks text,
  decided_by bigint,
  decided_at timestamp with time zone,
  reference_number text,
  completed_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT student_service_request_pkey PRIMARY KEY (service_request_id),
  CONSTRAINT student_service_request_reference_number_key UNIQUE (reference_number),
  CONSTRAINT student_service_request_request_kind_check CHECK (request_kind = ANY (ARRAY['HALL_TICKET'::text, 'HOSTEL_CHECKOUT'::text, 'GRADUATION'::text])),
  CONSTRAINT student_service_request_request_number_key UNIQUE (request_number),
  CONSTRAINT student_service_request_request_status_check CHECK (request_status = ANY (ARRAY['SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text, 'COMPLETED'::text, 'CANCELLED'::text]))
);
CREATE TABLE public.building (
  building_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  campus_id u16 NOT NULL,
  building_code character varying(20) NOT NULL,
  building_name character varying(100) NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  CONSTRAINT building_pkey PRIMARY KEY (building_id),
  CONSTRAINT uq_building_code UNIQUE (campus_id, building_code)
);
CREATE TABLE public.department (
  department_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  campus_id u16 NOT NULL,
  department_code character varying(20) NOT NULL,
  department_name character varying(150) NOT NULL,
  department_type character varying(30),
  is_active boolean NOT NULL DEFAULT true,
  CONSTRAINT department_pkey PRIMARY KEY (department_id),
  CONSTRAINT uq_department_code UNIQUE (campus_id, department_code),
  CONSTRAINT uq_department_id_campus UNIQUE (department_id, campus_id)
);
CREATE TABLE public.employee (
  employee_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  institution_id u16 NOT NULL,
  employment_source_id u8 NOT NULL,
  external_agency_id u64,
  employee_number character varying(30) NOT NULL,
  agency_employee_number character varying(50),
  first_name character varying(100) NOT NULL,
  middle_name character varying(100),
  last_name character varying(100),
  display_name character varying(250) NOT NULL,
  date_of_birth date,
  gender_id u8,
  blood_group_id u8,
  primary_email character varying(254),
  primary_phone character varying(25),
  nationality_country_id u16,
  religion_id u16,
  social_category_id u16,
  caste_id u32,
  sub_caste_id u32,
  photo_url character varying(500),
  joining_date date NOT NULL,
  employment_type text NOT NULL,
  employment_status text NOT NULL DEFAULT 'ACTIVE'::text,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT employee_employee_number_key UNIQUE (employee_number),
  CONSTRAINT employee_pkey PRIMARY KEY (employee_id),
  CONSTRAINT enum_employment_status CHECK (employment_status = ANY (ARRAY['ACTIVE'::text, 'ON_LEAVE'::text, 'SUSPENDED'::text, 'RESIGNED'::text, 'RETIRED'::text, 'TERMINATED'::text])),
  CONSTRAINT enum_employment_type CHECK (employment_type = ANY (ARRAY['REGULAR'::text, 'CONTRACT'::text, 'VISITING'::text, 'ADJUNCT'::text, 'TEMPORARY'::text, 'OTHER'::text])),
  CONSTRAINT uq_employee_agency_number UNIQUE (external_agency_id, agency_employee_number),
  CONSTRAINT uq_employee_primary_email UNIQUE (primary_email)
);
CREATE TABLE public.journal_metric (
  journal_metric_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  journal_id u64 NOT NULL,
  metric_type_id u8 NOT NULL,
  metric_year u_year NOT NULL,
  metric_value numeric(12,4) NOT NULL,
  quartile character varying(10),
  source_name character varying(150),
  source_url character varying(1000),
  verified_at timestamp with time zone,
  CONSTRAINT chk_journal_metric_value CHECK (metric_value >= 0::numeric),
  CONSTRAINT journal_metric_pkey PRIMARY KEY (journal_metric_id),
  CONSTRAINT uq_journal_metric UNIQUE (journal_id, metric_type_id, metric_year)
);
CREATE TABLE public.student_financial_hold (
  financial_hold_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  student_account_id u64 NOT NULL,
  hold_type text NOT NULL,
  hold_reason character varying(500) NOT NULL,
  placed_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  placed_by u64 NOT NULL,
  released_at timestamp with time zone,
  released_by u64,
  release_reason character varying(500),
  hold_status text NOT NULL DEFAULT 'ACTIVE'::text,
  CONSTRAINT enum_hold_status CHECK (hold_status = ANY (ARRAY['ACTIVE'::text, 'RELEASED'::text, 'CANCELLED'::text])),
  CONSTRAINT enum_hold_type CHECK (hold_type = ANY (ARRAY['REGISTRATION'::text, 'EXAMINATION'::text, 'HALL_TICKET'::text, 'RESULT'::text, 'CERTIFICATE'::text, 'HOSTEL_CHECKOUT'::text, 'GRADUATION'::text, 'OTHER'::text])),
  CONSTRAINT student_financial_hold_pkey PRIMARY KEY (financial_hold_id)
);
CREATE TABLE public.time_slot (
  time_slot_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  campus_id u16 NOT NULL,
  slot_code character varying(20) NOT NULL,
  start_time time without time zone NOT NULL,
  end_time time without time zone NOT NULL,
  is_break boolean NOT NULL DEFAULT false,
  is_active boolean NOT NULL DEFAULT true,
  CONSTRAINT chk_time_slot CHECK (end_time > start_time),
  CONSTRAINT time_slot_pkey PRIMARY KEY (time_slot_id),
  CONSTRAINT uq_time_slot UNIQUE (campus_id, slot_code)
);
CREATE TABLE public.announcement (
  announcement_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  announcement_type_id u16 NOT NULL,
  department_id u16,
  title character varying(250) NOT NULL,
  description text NOT NULL,
  publish_from timestamp with time zone NOT NULL,
  publish_to timestamp with time zone,
  approval_status text NOT NULL DEFAULT 'DRAFT'::text,
  audience_type text NOT NULL DEFAULT 'ALL'::text,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT announcement_pkey PRIMARY KEY (announcement_id),
  CONSTRAINT enum_approval_status CHECK (approval_status = ANY (ARRAY['DRAFT'::text, 'PENDING'::text, 'APPROVED'::text, 'REJECTED'::text, 'ARCHIVED'::text])),
  CONSTRAINT enum_audience_type CHECK (audience_type = ANY (ARRAY['ALL'::text, 'STUDENTS'::text, 'STAFF'::text, 'PROGRAMME'::text, 'DEPARTMENT'::text, 'CUSTOM'::text]))
);
CREATE TABLE public.course_catalog (
  course_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  owning_department_id u16 NOT NULL,
  course_category_id u16 NOT NULL,
  course_code character varying(30) NOT NULL,
  course_title character varying(200) NOT NULL,
  short_title character varying(80),
  course_type text NOT NULL,
  lecture_hours numeric(4,1) NOT NULL DEFAULT 0,
  tutorial_hours numeric(4,1) NOT NULL DEFAULT 0,
  practical_hours numeric(4,1) NOT NULL DEFAULT 0,
  self_study_hours numeric(4,1) NOT NULL DEFAULT 0,
  credits numeric(4,1) NOT NULL DEFAULT 0,
  effective_from date,
  effective_to date,
  is_active boolean NOT NULL DEFAULT true,
  CONSTRAINT chk_course_effective_dates CHECK (effective_from IS NULL OR effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT chk_course_nonnegative_values CHECK (lecture_hours >= 0::numeric AND tutorial_hours >= 0::numeric AND practical_hours >= 0::numeric AND self_study_hours >= 0::numeric AND credits >= 0::numeric),
  CONSTRAINT course_catalog_course_code_key UNIQUE (course_code),
  CONSTRAINT course_catalog_pkey PRIMARY KEY (course_id),
  CONSTRAINT enum_course_type CHECK (course_type = ANY (ARRAY['THEORY'::text, 'LAB'::text, 'THEORY_LAB'::text, 'PROJECT'::text, 'SEMINAR'::text, 'INTERNSHIP'::text, 'OTHER'::text]))
);
CREATE TABLE public.employee_aadhaar (
  employee_aadhaar_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  employee_id u64 NOT NULL,
  aadhaar_number_ciphertext bytea NOT NULL,
  aadhaar_number_fingerprint character(64) NOT NULL,
  aadhaar_number_last4 character(4) NOT NULL,
  aadhaar_number_masked character varying(30) NOT NULL,
  name_as_per_aadhaar character varying(200) NOT NULL,
  format_validated boolean NOT NULL DEFAULT false,
  verification_status text NOT NULL DEFAULT 'PENDING'::text,
  verified_by_user_id u64,
  verified_at timestamp with time zone,
  verification_remarks character varying(1000),
  collection_purpose character varying(500),
  remarks character varying(1000),
  created_by_user_id u64,
  updated_by_user_id u64,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at timestamp with time zone,
  CONSTRAINT chk_employee_aadhaar_last4 CHECK (aadhaar_number_last4 ~ '^[0-9]{4}$'::text),
  CONSTRAINT employee_aadhaar_aadhaar_number_fingerprint_key UNIQUE (aadhaar_number_fingerprint),
  CONSTRAINT employee_aadhaar_employee_id_key UNIQUE (employee_id),
  CONSTRAINT employee_aadhaar_pkey PRIMARY KEY (employee_aadhaar_id),
  CONSTRAINT enum_verification_status CHECK (verification_status = ANY (ARRAY['PENDING'::text, 'VERIFIED'::text, 'REJECTED'::text, 'EXPIRED'::text])),
  CONSTRAINT uq_employee_aadhaar_owner UNIQUE (employee_aadhaar_id, employee_id)
);
CREATE TABLE public.employee_address (
  employee_address_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  employee_id u64 NOT NULL,
  address_type text NOT NULL,
  address_line_1 character varying(200) NOT NULL,
  address_line_2 character varying(200),
  city character varying(100) NOT NULL,
  state_id u16,
  country_id u16 NOT NULL,
  postal_code character varying(12),
  valid_from date,
  valid_to date,
  is_primary boolean NOT NULL DEFAULT false,
  current_primary_employee_id u64 GENERATED ALWAYS AS (
CASE
    WHEN ((is_primary = true) AND (valid_to IS NULL)) THEN (employee_id)::bigint
    ELSE NULL::bigint
END) STORED,
  CONSTRAINT chk_employee_address_dates CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from),
  CONSTRAINT employee_address_pkey PRIMARY KEY (employee_address_id),
  CONSTRAINT enum_address_type CHECK (address_type = ANY (ARRAY['PERMANENT'::text, 'CURRENT'::text, 'CORRESPONDENCE'::text, 'OTHER'::text])),
  CONSTRAINT uq_employee_current_primary_address UNIQUE (current_primary_employee_id)
);
CREATE TABLE public.employee_assignment (
  employee_assignment_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  employee_id u64 NOT NULL,
  campus_id u16 NOT NULL,
  department_id u16,
  designation_id u16 NOT NULL,
  start_date date NOT NULL,
  end_date date,
  is_primary boolean NOT NULL DEFAULT true,
  current_primary_employee_id u64 GENERATED ALWAYS AS (
CASE
    WHEN ((is_primary = true) AND (end_date IS NULL)) THEN (employee_id)::bigint
    ELSE NULL::bigint
END) STORED,
  CONSTRAINT chk_employee_assignment_dates CHECK (end_date IS NULL OR end_date >= start_date),
  CONSTRAINT employee_assignment_pkey PRIMARY KEY (employee_assignment_id),
  CONSTRAINT uq_employee_current_primary UNIQUE (current_primary_employee_id)
);
CREATE TABLE public.employee_bank_account (
  employee_bank_account_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  employee_id u64 NOT NULL,
  account_holder_name character varying(200) NOT NULL,
  bank_name character varying(200) NOT NULL,
  branch_name character varying(200),
  account_number_ciphertext bytea NOT NULL,
  account_number_fingerprint character(64) NOT NULL,
  account_number_last4 character(4) NOT NULL,
  account_number_confirmed boolean NOT NULL DEFAULT false,
  account_type text NOT NULL DEFAULT 'SAVINGS'::text,
  ifsc_code character varying(11) NOT NULL,
  micr_code character varying(20),
  branch_code character varying(30),
  bank_address character varying(500),
  city character varying(100),
  state_id u16,
  country_id u16,
  upi_id character varying(150),
  is_salary_account boolean NOT NULL DEFAULT false,
  is_primary boolean NOT NULL DEFAULT false,
  account_status text NOT NULL DEFAULT 'PENDING_VERIFICATION'::text,
  verification_status text NOT NULL DEFAULT 'PENDING'::text,
  verified_by_user_id u64,
  verified_at timestamp with time zone,
  verification_remarks character varying(1000),
  effective_from date,
  effective_to date,
  remarks character varying(1000),
  created_by_user_id u64,
  updated_by_user_id u64,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at timestamp with time zone,
  active_primary_employee_id u64 GENERATED ALWAYS AS (
CASE
    WHEN ((is_primary = true) AND (deleted_at IS NULL)) THEN (employee_id)::bigint
    ELSE NULL::bigint
END) STORED,
  CONSTRAINT chk_employee_bank_dates CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from),
  CONSTRAINT chk_employee_bank_ifsc CHECK (ifsc_code::text ~ '^[A-Za-z]{4}0[A-Za-z0-9]{6}$'::text),
  CONSTRAINT chk_employee_bank_last4 CHECK (account_number_last4 ~ '^[0-9]{4}$'::text),
  CONSTRAINT employee_bank_account_account_number_fingerprint_key UNIQUE (account_number_fingerprint),
  CONSTRAINT employee_bank_account_pkey PRIMARY KEY (employee_bank_account_id),
  CONSTRAINT enum_account_status CHECK (account_status = ANY (ARRAY['PENDING_VERIFICATION'::text, 'ACTIVE'::text, 'INACTIVE'::text, 'CLOSED'::text, 'REJECTED'::text])),
  CONSTRAINT enum_account_type CHECK (account_type = ANY (ARRAY['SAVINGS'::text, 'CURRENT'::text, 'SALARY'::text, 'NRE'::text, 'NRO'::text, 'OTHER'::text])),
  CONSTRAINT enum_verification_status CHECK (verification_status = ANY (ARRAY['PENDING'::text, 'VERIFIED'::text, 'REJECTED'::text, 'EXPIRED'::text])),
  CONSTRAINT uq_employee_bank_owner UNIQUE (employee_bank_account_id, employee_id),
  CONSTRAINT uq_employee_primary_bank UNIQUE (active_primary_employee_id)
);
CREATE TABLE public.employee_pan (
  employee_pan_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  employee_id u64 NOT NULL,
  pan_number_ciphertext bytea NOT NULL,
  pan_number_fingerprint character(64) NOT NULL,
  pan_number_masked character varying(15) NOT NULL,
  name_as_per_pan character varying(200) NOT NULL,
  pan_issue_date date,
  pan_issue_details character varying(500),
  format_validated boolean NOT NULL DEFAULT false,
  verification_status text NOT NULL DEFAULT 'PENDING'::text,
  verified_by_user_id u64,
  verified_at timestamp with time zone,
  verification_remarks character varying(1000),
  remarks character varying(1000),
  created_by_user_id u64,
  updated_by_user_id u64,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at timestamp with time zone,
  CONSTRAINT chk_employee_pan_masked CHECK (char_length(pan_number_masked::text) >= 6 AND char_length(pan_number_masked::text) <= 15),
  CONSTRAINT employee_pan_employee_id_key UNIQUE (employee_id),
  CONSTRAINT employee_pan_pan_number_fingerprint_key UNIQUE (pan_number_fingerprint),
  CONSTRAINT employee_pan_pkey PRIMARY KEY (employee_pan_id),
  CONSTRAINT enum_verification_status CHECK (verification_status = ANY (ARRAY['PENDING'::text, 'VERIFIED'::text, 'REJECTED'::text, 'EXPIRED'::text])),
  CONSTRAINT uq_employee_pan_owner UNIQUE (employee_pan_id, employee_id)
);
CREATE TABLE public.employee_previous_employment (
  employee_previous_employment_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
