  previous_organization_id u64 NOT NULL,
  department_division character varying(200),
  designation character varying(150) NOT NULL,
  employment_type text NOT NULL,
  nature_of_work character varying(1000),
  employment_start_date date NOT NULL,
  employment_end_date date,
  experience_days u32,
  last_drawn_salary numeric(14,2),
  salary_currency_code character(3) NOT NULL DEFAULT 'INR'::bpchar,
  reason_for_leaving character varying(1000),
  reporting_authority_name character varying(200),
  reporting_authority_designation character varying(150),
  reporting_authority_phone character varying(25),
  reporting_authority_email character varying(254),
  remarks character varying(1000),
  created_by_user_id u64,
  updated_by_user_id u64,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at timestamp with time zone,
  CONSTRAINT chk_previous_employment_dates CHECK (employment_end_date IS NULL OR employment_end_date >= employment_start_date),
  CONSTRAINT chk_previous_employment_salary CHECK (last_drawn_salary IS NULL OR last_drawn_salary >= 0::numeric),
  CONSTRAINT employee_previous_employment_pkey PRIMARY KEY (employee_previous_employment_id),
  CONSTRAINT enum_employment_type CHECK (employment_type = ANY (ARRAY['FULL_TIME'::text, 'PART_TIME'::text, 'CONTRACT'::text, 'TEMPORARY'::text, 'VISITING'::text, 'CONSULTANT'::text, 'TRAINEE'::text, 'SELF_EMPLOYED'::text, 'OTHER'::text])),
  CONSTRAINT uq_employee_previous_employment_owner UNIQUE (employee_previous_employment_id, employee_id)
);
CREATE TABLE public.employee_qualification (
  employee_qualification_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  employee_id u64 NOT NULL,
  qualification_level_id u16 NOT NULL,
  education_institution_id u64,
  awarding_body_id u64,
  study_mode_id u8,
  degree_certificate_name character varying(250) NOT NULL,
  specialization character varying(200),
  course_program_name character varying(250),
  start_date date,
  start_year u_year,
  completion_date date,
  completion_year u_year,
  passing_year u_year,
  registration_roll_number character varying(100),
  result character varying(100),
  class_grade character varying(100),
  cgpa numeric(6,3),
  cgpa_scale numeric(6,3),
  percentage numeric(5,2),
  maximum_marks numeric(10,2),
  marks_obtained numeric(10,2),
  qualification_status text NOT NULL DEFAULT 'COMPLETED'::text,
  is_highest_qualification boolean NOT NULL DEFAULT false,
  active_highest_employee_id u64 GENERATED ALWAYS AS (
CASE
    WHEN ((is_highest_qualification = true) AND (deleted_at IS NULL)) THEN (employee_id)::bigint
    ELSE NULL::bigint
END) STORED,
  remarks character varying(1000),
  created_by_user_id u64,
  updated_by_user_id u64,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at timestamp with time zone,
  CONSTRAINT chk_employee_qualification_cgpa CHECK (cgpa IS NULL OR cgpa >= 0::numeric),
  CONSTRAINT chk_employee_qualification_cgpa_range CHECK (cgpa IS NULL OR cgpa_scale IS NULL OR cgpa <= cgpa_scale),
  CONSTRAINT chk_employee_qualification_cgpa_scale CHECK (cgpa_scale IS NULL OR cgpa_scale > 0::numeric),
  CONSTRAINT chk_employee_qualification_dates CHECK (completion_date IS NULL OR start_date IS NULL OR completion_date >= start_date),
  CONSTRAINT chk_employee_qualification_marks CHECK (marks_obtained IS NULL OR maximum_marks IS NULL OR marks_obtained >= 0::numeric AND maximum_marks >= 0::numeric AND marks_obtained <= maximum_marks),
  CONSTRAINT chk_employee_qualification_percentage CHECK (percentage IS NULL OR percentage >= 0::numeric AND percentage <= 100::numeric),
  CONSTRAINT employee_qualification_pkey PRIMARY KEY (employee_qualification_id),
  CONSTRAINT enum_qualification_status CHECK (qualification_status = ANY (ARRAY['COMPLETED'::text, 'PURSUING'::text, 'AWAITING_RESULT'::text, 'DISCONTINUED'::text, 'OTHER'::text])),
  CONSTRAINT uq_employee_highest_qualification UNIQUE (active_highest_employee_id),
  CONSTRAINT uq_employee_qualification_owner UNIQUE (employee_qualification_id, employee_id)
);
CREATE TABLE public.employee_user_account (
