  CONSTRAINT enum_status CHECK (status = ANY (ARRAY['SUBMITTED'::text, 'ASSIGNED'::text, 'UNDER_REVIEW'::text, 'RESOLVED'::text, 'REJECTED'::text, 'CLOSED'::text])),
  CONSTRAINT grievance_grievance_number_key UNIQUE (grievance_number),
