CREATE TABLE public.user_role_assignment (
  user_role_assignment_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id u64 NOT NULL,
  role_id u16 NOT NULL,
  scope_type text NOT NULL DEFAULT 'GLOBAL'::text,
  institution_id u16,
  campus_id u16,
  department_id u16,
  programme_id u16,
  scope_entity_id u64 GENERATED ALWAYS AS (
CASE scope_type
    WHEN 'GLOBAL'::text THEN (0)::bigint
    WHEN 'INSTITUTION'::text THEN (institution_id)::bigint
    WHEN 'CAMPUS'::text THEN (campus_id)::bigint
    WHEN 'DEPARTMENT'::text THEN (department_id)::bigint
    WHEN 'PROGRAMME'::text THEN (programme_id)::bigint
    WHEN 'SELF'::text THEN (user_id)::bigint
    ELSE NULL::bigint
END) STORED,
  valid_from timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  valid_to timestamp with time zone,
  assignment_status text NOT NULL DEFAULT 'ACTIVE'::text,
  is_primary boolean NOT NULL DEFAULT false,
  assigned_by_user_id u64,
  assignment_reason character varying(500),
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_user_role_dates CHECK (valid_to IS NULL OR valid_to > valid_from),
  CONSTRAINT chk_user_role_scope CHECK (scope_type = 'GLOBAL'::text AND institution_id IS NULL AND campus_id IS NULL AND department_id IS NULL AND programme_id IS NULL OR scope_type = 'INSTITUTION'::text AND institution_id IS NOT NULL AND campus_id IS NULL AND department_id IS NULL AND programme_id IS NULL OR scope_type = 'CAMPUS'::text AND institution_id IS NULL AND campus_id IS NOT NULL AND department_id IS NULL AND programme_id IS NULL OR scope_type = 'DEPARTMENT'::text AND institution_id IS NULL AND campus_id IS NULL AND department_id IS NOT NULL AND programme_id IS NULL OR scope_type = 'PROGRAMME'::text AND institution_id IS NULL AND campus_id IS NULL AND department_id IS NULL AND programme_id IS NOT NULL OR scope_type = 'SELF'::text AND institution_id IS NULL AND campus_id IS NULL AND department_id IS NULL AND programme_id IS NULL),
  CONSTRAINT enum_assignment_status CHECK (assignment_status = ANY (ARRAY['PENDING'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'EXPIRED'::text, 'REVOKED'::text])),
  CONSTRAINT enum_scope_type CHECK (scope_type = ANY (ARRAY['GLOBAL'::text, 'INSTITUTION'::text, 'CAMPUS'::text, 'DEPARTMENT'::text, 'PROGRAMME'::text, 'SELF'::text])),
  CONSTRAINT uq_user_role_assignment UNIQUE (user_id, role_id, scope_type, scope_entity_id, valid_from),
  CONSTRAINT user_role_assignment_pkey PRIMARY KEY (user_role_assignment_id)
);
