  approved_amount numeric(12,2),
  request_status text NOT NULL DEFAULT 'SUBMITTED'::text,
  approved_by u64,
  approved_at timestamp with time zone,
  CONSTRAINT chk_refund_request_amounts CHECK (requested_amount > 0::numeric AND (approved_amount IS NULL OR approved_amount >= 0::numeric AND approved_amount <= requested_amount)),
  CONSTRAINT enum_request_status CHECK (request_status = ANY (ARRAY['SUBMITTED'::text, 'UNDER_REVIEW'::text, 'APPROVED'::text, 'REJECTED'::text, 'PROCESSED'::text, 'CANCELLED'::text])),
  CONSTRAINT refund_request_pkey PRIMARY KEY (refund_request_id),
  CONSTRAINT refund_request_refund_request_number_key UNIQUE (refund_request_number)
);
CREATE TABLE public.student_activity_evidence_audit (
