  CONSTRAINT student_exit_pkey PRIMARY KEY (student_exit_id),
  CONSTRAINT uq_student_exit_enrolment UNIQUE (enrolment_id)
);
CREATE TABLE public.assessment_component (
  assessment_component_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
