  CONSTRAINT enum_refund_status CHECK (refund_status = ANY (ARRAY['INITIATED'::text, 'PROCESSING'::text, 'SUCCESS'::text, 'FAILED'::text, 'CANCELLED'::text])),
  CONSTRAINT fee_refund_pkey PRIMARY KEY (fee_refund_id),
  CONSTRAINT fee_refund_refund_transaction_number_key UNIQUE (refund_transaction_number)
);
CREATE TABLE public.assessment_event (
  assessment_event_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  assessment_component_id u64 NOT NULL,
  course_offering_id u64 NOT NULL,
  event_number u16,
  event_title character varying(150) NOT NULL,
  assessment_date date NOT NULL,
  start_time time without time zone,
  end_time time without time zone,
  maximum_marks numeric(7,2) NOT NULL,
  reduced_maximum_marks numeric(7,2),
  details text,
  status text NOT NULL DEFAULT 'PLANNED'::text,
  CONSTRAINT assessment_event_pkey PRIMARY KEY (assessment_event_id),
  CONSTRAINT chk_assessment_event_marks CHECK (maximum_marks >= 0::numeric AND (reduced_maximum_marks IS NULL OR reduced_maximum_marks >= 0::numeric)),
  CONSTRAINT chk_assessment_event_time CHECK (end_time IS NULL OR start_time IS NULL OR end_time > start_time),
  CONSTRAINT enum_status CHECK (status = ANY (ARRAY['PLANNED'::text, 'CONDUCTED'::text, 'CANCELLED'::text, 'PUBLISHED'::text])),
  CONSTRAINT uq_assessment_event_owner UNIQUE (assessment_event_id, course_offering_id)
);
CREATE TABLE public.course_offering_section (
