  CONSTRAINT enum_registration_type CHECK (registration_type = ANY (ARRAY['REGULAR'::text, 'ELECTIVE'::text, 'BACKLOG'::text, 'REPEAT'::text, 'IMPROVEMENT'::text, 'AUDIT'::text, 'CREDIT_TRANSFER'::text])),
  CONSTRAINT student_course_registration_pkey PRIMARY KEY (course_registration_id),
  CONSTRAINT uq_course_registration_owner UNIQUE (course_registration_id, course_offering_id),
