CREATE TABLE public.student_fee_assessment (
  fee_assessment_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  assessment_number character varying(50) NOT NULL,
  student_account_id u64,
  application_id u64,
  enrolment_id u64,
  term_registration_id u64,
  academic_year_id u16 NOT NULL,
  academic_term_id u32,
  fee_structure_id u64,
  assessment_type text NOT NULL,
  assessment_date date NOT NULL,
  gross_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  concession_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  scholarship_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  adjustment_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  net_payable_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  amount_paid numeric(12,2) NOT NULL DEFAULT 0.00,
  balance_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  due_date date,
  assessment_status text NOT NULL DEFAULT 'DRAFT'::text,
  remarks character varying(500),
  created_by u64,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_fee_assessment_amounts CHECK (gross_amount >= 0::numeric AND concession_amount >= 0::numeric AND scholarship_amount >= 0::numeric AND net_payable_amount >= 0::numeric AND amount_paid >= 0::numeric AND amount_paid <= net_payable_amount AND net_payable_amount = (gross_amount - concession_amount - scholarship_amount + adjustment_amount) AND balance_amount = (net_payable_amount - amount_paid)),
  CONSTRAINT chk_fee_assessment_context CHECK (student_account_id IS NOT NULL OR application_id IS NOT NULL),
  CONSTRAINT enum_assessment_status CHECK (assessment_status = ANY (ARRAY['DRAFT'::text, 'ASSESSED'::text, 'PARTIALLY_PAID'::text, 'PAID'::text, 'OVERDUE'::text, 'CANCELLED'::text, 'WAIVED'::text])),
  CONSTRAINT enum_assessment_type CHECK (assessment_type = ANY (ARRAY['ADMISSION'::text, 'ACADEMIC'::text, 'EXAMINATION'::text, 'HOSTEL'::text, 'TRANSPORT'::text, 'LIBRARY'::text, 'CERTIFICATE'::text, 'PENALTY'::text, 'SERVICE'::text, 'OTHER'::text])),
  CONSTRAINT student_fee_assessment_assessment_number_key UNIQUE (assessment_number),
  CONSTRAINT student_fee_assessment_pkey PRIMARY KEY (fee_assessment_id)
);
