  CONSTRAINT enum_request_status CHECK (request_status = ANY (ARRAY['DRAFT'::text, 'SUBMITTED'::text, 'ASSESSED'::text, 'PAID'::text, 'PROCESSING'::text, 'COMPLETED'::text, 'REJECTED'::text, 'CANCELLED'::text])),
  CONSTRAINT service_fee_request_pkey PRIMARY KEY (service_fee_request_id),
  CONSTRAINT service_fee_request_request_number_key UNIQUE (request_number)
);
