  CONSTRAINT chk_student_assessment_reduced_marks CHECK (reduced_marks IS NULL OR reduced_marks >= 0::numeric),
  CONSTRAINT enum_attendance_status CHECK (attendance_status = ANY (ARRAY['PRESENT'::text, 'ABSENT'::text, 'EXEMPTED'::text, 'MALPRACTICE'::text])),
