CREATE TABLE public.student_fee_assessment_item (
  assessment_item_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  fee_assessment_id u64 NOT NULL,
  fee_type_id u32 NOT NULL,
  fee_structure_item_id u64,
  description character varying(250),
  original_amount numeric(12,2) NOT NULL,
  concession_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  scholarship_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  adjustment_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  net_amount numeric(12,2) NOT NULL,
  amount_paid numeric(12,2) NOT NULL DEFAULT 0.00,
  balance_amount numeric(12,2) NOT NULL,
  due_date date,
  item_status text NOT NULL DEFAULT 'ASSESSED'::text,
  CONSTRAINT chk_fee_assessment_item_amounts CHECK (original_amount >= 0::numeric AND concession_amount >= 0::numeric AND scholarship_amount >= 0::numeric AND net_amount >= 0::numeric AND amount_paid >= 0::numeric AND amount_paid <= net_amount AND net_amount = (original_amount - concession_amount - scholarship_amount + adjustment_amount) AND balance_amount = (net_amount - amount_paid)),
  CONSTRAINT enum_item_status CHECK (item_status = ANY (ARRAY['ASSESSED'::text, 'PARTIALLY_PAID'::text, 'PAID'::text, 'OVERDUE'::text, 'CANCELLED'::text, 'WAIVED'::text])),
  CONSTRAINT student_fee_assessment_item_pkey PRIMARY KEY (assessment_item_id)
