  CONSTRAINT enum_session_type CHECK (session_type = ANY (ARRAY['LECTURE'::text, 'TUTORIAL'::text, 'PRACTICAL'::text, 'PROJECT'::text, 'SEMINAR'::text, 'OTHER'::text])),
  CONSTRAINT uq_class_session UNIQUE (course_offering_section_id, session_date, start_time),
