  CONSTRAINT enum_adjustment_type CHECK (adjustment_type = ANY (ARRAY['CREDIT'::text, 'DEBIT'::text, 'WAIVER'::text, 'WRITE_OFF'::text, 'TRANSFER'::text, 'CORRECTION'::text])),
  CONSTRAINT enum_approval_status CHECK (approval_status = ANY (ARRAY['DRAFT'::text, 'SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text, 'CANCELLED'::text])),
  CONSTRAINT fee_adjustment_adjustment_number_key UNIQUE (adjustment_number),
  CONSTRAINT fee_adjustment_pkey PRIMARY KEY (fee_adjustment_id)
