  student_concession_id u64,
  student_scholarship_id u64,
  student_sponsorship_id u64,
  benefit_amount numeric(12,2) NOT NULL,
  applied_date date NOT NULL,
  approved_by u64,
  CONSTRAINT chk_fee_benefit_amount CHECK (benefit_amount > 0::numeric),
  CONSTRAINT chk_fee_benefit_source CHECK (benefit_type = 'CONCESSION'::text AND student_concession_id IS NOT NULL AND student_scholarship_id IS NULL AND student_sponsorship_id IS NULL OR benefit_type = 'SCHOLARSHIP'::text AND student_concession_id IS NULL AND student_scholarship_id IS NOT NULL AND student_sponsorship_id IS NULL OR benefit_type = 'SPONSORSHIP'::text AND student_concession_id IS NULL AND student_scholarship_id IS NULL AND student_sponsorship_id IS NOT NULL),
  CONSTRAINT enum_benefit_type CHECK (benefit_type = ANY (ARRAY['CONCESSION'::text, 'SCHOLARSHIP'::text, 'SPONSORSHIP'::text])),
  CONSTRAINT fee_assessment_benefit_pkey PRIMARY KEY (assessment_benefit_id)
);
