CREATE TABLE public.feedback_response_item (
  feedback_response_item_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  feedback_response_id u64 NOT NULL,
  questionnaire_item_id u64 NOT NULL,
  feedback_choice_id u32,
  numeric_score numeric(6,2),
  text_response text,
  CONSTRAINT feedback_response_item_pkey PRIMARY KEY (feedback_response_item_id),
  CONSTRAINT uq_feedback_response_item UNIQUE (feedback_response_id, questionnaire_item_id)
);
CREATE TABLE public.payment_allocation (
  payment_allocation_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  payment_transaction_id u64 NOT NULL,
  assessment_item_id u64 NOT NULL,
  allocated_amount numeric(12,2) NOT NULL,
  allocation_date timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  allocated_by u64,
  CONSTRAINT chk_allocated_amount CHECK (allocated_amount > 0::numeric),
  CONSTRAINT payment_allocation_pkey PRIMARY KEY (payment_allocation_id),
  CONSTRAINT uq_payment_allocation UNIQUE (payment_transaction_id, assessment_item_id)
);
CREATE TABLE public.student_fee_penalty (
  fee_penalty_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  student_account_id u64 NOT NULL,
  assessment_item_id u64,
  fee_type_id u32 NOT NULL,
  penalty_date date NOT NULL,
  penalty_reason character varying(500) NOT NULL,
  penalty_amount numeric(12,2) NOT NULL,
  waived_amount numeric(12,2) NOT NULL DEFAULT 0.00,
  net_penalty_amount numeric(12,2) NOT NULL,
  penalty_status text NOT NULL DEFAULT 'ASSESSED'::text,
  approved_by u64,
  CONSTRAINT enum_penalty_status CHECK (penalty_status = ANY (ARRAY['ASSESSED'::text, 'PARTIALLY_PAID'::text, 'PAID'::text, 'WAIVED'::text, 'CANCELLED'::text])),
  CONSTRAINT student_fee_penalty_pkey PRIMARY KEY (fee_penalty_id)
);
CREATE TABLE public.student_attendance (
  class_session_id u64 NOT NULL,
  course_offering_section_student_id u64 NOT NULL,
  course_offering_section_id u64 NOT NULL,
  attendance_status_id u8 NOT NULL,
  marked_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  marked_by_user_id u64,
  remarks character varying(500),
  CONSTRAINT student_attendance_pkey PRIMARY KEY (class_session_id, course_offering_section_student_id)
);
CREATE TABLE public.attendance_correction_request (
  attendance_correction_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  class_session_id u64 NOT NULL,
  course_offering_section_student_id u64 NOT NULL,
  old_status_id u8 NOT NULL,
  requested_status_id u8 NOT NULL,
  reason character varying(1000) NOT NULL,
  request_status text NOT NULL DEFAULT 'PENDING'::text,
  requested_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at timestamp with time zone,
  CONSTRAINT attendance_correction_request_pkey PRIMARY KEY (attendance_correction_id),
  CONSTRAINT enum_request_status CHECK (request_status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text, 'CANCELLED'::text]))
);

