-- -----------------------------------------------------------------------------
-- Views
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_active_user_role WITH (security_invoker=true) AS
 SELECT ura.user_role_assignment_id,
    ura.user_id,
    ura.role_id,
    r.role_code,
    r.role_name,
    ura.scope_type,
    ura.institution_id,
    ura.campus_id,
    ura.department_id,
    ura.programme_id,
    ura.valid_from,
    ura.valid_to
   FROM user_role_assignment ura
     JOIN role r ON r.role_id = ura.role_id::integer
  WHERE ura.assignment_status = 'ACTIVE'::text AND r.is_active = true AND ura.valid_from <= CURRENT_TIMESTAMP AND (ura.valid_to IS NULL OR ura.valid_to > CURRENT_TIMESTAMP);
CREATE OR REPLACE VIEW public.v_employee_previous_experience WITH (security_invoker=true) AS
 SELECT epe.employee_previous_employment_id,
    epe.employee_id,
    po.organization_name,
    epe.designation,
    epe.employment_type,
    epe.employment_start_date,
    epe.employment_end_date,
    COALESCE(epe.experience_days::bigint, (COALESCE(epe.employment_end_date, CURRENT_DATE) - epe.employment_start_date + 1)::bigint) AS calculated_experience_days,
    EXTRACT(year FROM age(COALESCE(epe.employment_end_date, CURRENT_DATE)::timestamp with time zone, epe.employment_start_date::timestamp with time zone))::integer AS completed_years,
    mod((EXTRACT(year FROM age(COALESCE(epe.employment_end_date, CURRENT_DATE)::timestamp with time zone, epe.employment_start_date::timestamp with time zone)) * 12::numeric + EXTRACT(month FROM age(COALESCE(epe.employment_end_date, CURRENT_DATE)::timestamp with time zone, epe.employment_start_date::timestamp with time zone)))::integer, 12) AS remaining_months
   FROM employee_previous_employment epe
     JOIN previous_organization po ON po.previous_organization_id = epe.previous_organization_id::bigint
  WHERE epe.deleted_at IS NULL;
CREATE OR REPLACE VIEW public.v_fee_collection_summary WITH (security_invoker=true) AS
 SELECT pt.transaction_date::date AS collection_date,
    pm.mode_code,
    count(*) AS transaction_count,
    sum(pt.amount) AS collected_amount
   FROM payment_transaction pt
     JOIN payment_mode pm ON pm.payment_mode_id = pt.payment_mode_id::smallint
  WHERE pt.payment_status = 'SUCCESS'::text
  GROUP BY (pt.transaction_date::date), pm.mode_code;
CREATE OR REPLACE VIEW public.v_staff_activity_profile WITH (security_invoker=true) AS
 SELECT sa.staff_activity_id,
    sa.employee_id,
    e.employee_number,
    e.display_name AS staff_name,
    at.activity_type_code,
    at.activity_type_name,
    at.activity_group,
    sa.activity_title,
    ay.year_code AS academic_year,
    u.university_name,
    i.institution_name,
    c.campus_name,
    d.department_name,
    pl.level_name AS participation_level,
    rt.role_name AS primary_role,
    sa.start_date,
    sa.end_date,
    vs.status_name AS verification_status,
    aps.status_name AS approval_status,
    sa.created_at,
    sa.updated_at,
    sa.deleted_at
   FROM staff_activity sa
     JOIN employee e ON e.employee_id = sa.employee_id::bigint
     JOIN activity_type at ON at.activity_type_id = sa.activity_type_id::integer
     LEFT JOIN academic_year ay ON ay.academic_year_id = sa.academic_year_id::integer
     JOIN institution i ON i.institution_id = sa.institution_id::integer
     JOIN university u ON u.university_id = i.university_id::integer
     LEFT JOIN campus c ON c.campus_id = sa.campus_id::integer
     LEFT JOIN department d ON d.department_id = sa.department_id::integer
     LEFT JOIN participation_level pl ON pl.participation_level_id = sa.participation_level_id::smallint
     LEFT JOIN role_type rt ON rt.role_type_id = sa.primary_role_type_id::integer
     JOIN verification_status vs ON vs.verification_status_id = sa.verification_status_id::smallint
     JOIN approval_status aps ON aps.approval_status_id = sa.approval_status_id::smallint;
CREATE OR REPLACE VIEW public.v_staff_evidence_search WITH (security_invoker=true) AS
 SELECT ed.evidence_document_id,
    ed.staff_activity_id,
    sa.employee_id,
    e.employee_number,
    e.display_name AS staff_name,
    d.department_id,
    d.department_name,
    at.activity_type_code,
    at.activity_type_name,
    ay.year_code AS academic_year,
    dt.document_code,
    dt.document_name,
    et.evidence_type_code,
    et.evidence_type_name,
    ed.document_title,
    ed.certificate_document_number,
    ed.document_issue_date,
    ed.expiry_date,
    vs.status_name AS verification_status,
    aps.status_name AS approval_status,
    cl.level_name AS confidentiality_level,
    ed.current_version_number,
    ed.is_active,
    ed.created_at,
    ed.updated_at,
    ed.deleted_at
   FROM evidence_document ed
     JOIN staff_activity sa ON sa.staff_activity_id = ed.staff_activity_id::bigint
     JOIN employee e ON e.employee_id = sa.employee_id::bigint
     JOIN activity_type at ON at.activity_type_id = sa.activity_type_id::integer
     LEFT JOIN academic_year ay ON ay.academic_year_id = ed.academic_year_id::integer
     LEFT JOIN department d ON d.department_id = sa.department_id::integer
     JOIN document_type dt ON dt.document_type_id = ed.document_type_id::integer
     LEFT JOIN evidence_type et ON et.evidence_type_id = ed.evidence_type_id::integer
     JOIN verification_status vs ON vs.verification_status_id = ed.verification_status_id::smallint
     JOIN approval_status aps ON aps.approval_status_id = ed.approval_status_id::smallint
     JOIN confidentiality_level cl ON cl.confidentiality_level_id = ed.confidentiality_level_id::smallint;
CREATE OR REPLACE VIEW public.v_student_activity_evidence_search WITH (security_invoker=true) AS
 SELECT sae.student_activity_evidence_id,
    sae.student_activity_id,
    sa.student_id,
    s.student_number,
    s.display_name AS student_name,
    sat.type_code AS activity_type_code,
    sat.type_name AS activity_type_name,
    d.department_id,
    d.department_name,
    p.programme_id,
    p.programme_name,
    ay.year_code AS academic_year,
    dt.document_code,
    dt.document_name,
    et.evidence_type_code,
    et.evidence_type_name,
    sae.document_title,
    sae.certificate_document_number,
    sae.document_issue_date,
    sae.expiry_date,
    vs.status_name AS verification_status,
    aps.status_name AS approval_status,
    cl.level_name AS confidentiality_level,
    sae.current_version_number,
    sae.is_active,
    sae.created_at,
    sae.updated_at,
    sae.deleted_at
   FROM student_activity_evidence sae
     JOIN student_activity sa ON sa.student_activity_id = sae.student_activity_id::bigint
     JOIN student s ON s.student_id = sa.student_id::bigint
     JOIN student_activity_type sat ON sat.student_activity_type_id = sa.student_activity_type_id::integer
     LEFT JOIN academic_year ay ON ay.academic_year_id = sae.academic_year_id::integer
     LEFT JOIN department d ON d.department_id = sa.department_id::integer
     LEFT JOIN programme p ON p.programme_id = sa.programme_id::integer
     JOIN document_type dt ON dt.document_type_id = sae.document_type_id::integer
     LEFT JOIN evidence_type et ON et.evidence_type_id = sae.evidence_type_id::integer
     JOIN verification_status vs ON vs.verification_status_id = sae.verification_status_id::smallint
     JOIN approval_status aps ON aps.approval_status_id = sae.approval_status_id::smallint
     JOIN confidentiality_level cl ON cl.confidentiality_level_id = sae.confidentiality_level_id::smallint;
CREATE OR REPLACE VIEW public.v_student_activity_profile WITH (security_invoker=true) AS
 SELECT sa.student_activity_id,
    sa.student_id,
    s.student_number,
    s.display_name AS student_name,
    sat.type_code AS activity_type_code,
    sat.type_name AS activity_type_name,
    sat.activity_group,
    sa.activity_title,
    sa.event_name,
    ay.year_code AS academic_year,
    i.institution_name,
    c.campus_name,
    d.department_name,
    p.programme_name,
    pl.level_name AS participation_level,
    em.mode_name AS event_mode,
    sa.start_date,
    sa.end_date,
    sa.achievement_type,
    sa.position_rank,
    sa.award_name,
    sa.cash_prize_amount,
    vs.status_name AS verification_status,
    aps.status_name AS approval_status,
    sa.created_at,
    sa.updated_at,
    sa.deleted_at
   FROM student_activity sa
     JOIN student s ON s.student_id = sa.student_id::bigint
     JOIN student_activity_type sat ON sat.student_activity_type_id = sa.student_activity_type_id::integer
     LEFT JOIN academic_year ay ON ay.academic_year_id = sa.academic_year_id::integer
     JOIN institution i ON i.institution_id = sa.institution_id::integer
     LEFT JOIN campus c ON c.campus_id = sa.campus_id::integer
     LEFT JOIN department d ON d.department_id = sa.department_id::integer
     LEFT JOIN programme p ON p.programme_id = sa.programme_id::integer
     LEFT JOIN participation_level pl ON pl.participation_level_id = sa.participation_level_id::smallint
     LEFT JOIN event_mode em ON em.event_mode_id = sa.event_mode_id::smallint
     JOIN verification_status vs ON vs.verification_status_id = sa.verification_status_id::smallint
     JOIN approval_status aps ON aps.approval_status_id = sa.approval_status_id::smallint;
CREATE OR REPLACE VIEW public.v_student_fee_balance WITH (security_invoker=true) AS
 SELECT sfa.student_account_id,
    sfa.student_id,
    sfa.account_number,
    COALESCE(sum(sfa2.net_payable_amount), 0.00) AS total_assessed,
    COALESCE(sum(sfa2.amount_paid), 0.00) AS total_paid,
    COALESCE(sum(sfa2.balance_amount), 0.00) AS total_outstanding,
    sfa.credit_balance
   FROM student_financial_account sfa
     LEFT JOIN student_fee_assessment sfa2 ON sfa2.student_account_id::bigint = sfa.student_account_id AND (sfa2.assessment_status <> ALL (ARRAY['CANCELLED'::text, 'WAIVED'::text]))
  GROUP BY sfa.student_account_id, sfa.student_id, sfa.account_number, sfa.credit_balance;
CREATE OR REPLACE VIEW public.v_active_role_permission WITH (security_invoker=true) AS
 SELECT aur.user_id,
    aur.user_role_assignment_id AS source_assignment_id,
    aur.role_id,
    aur.role_code,
    aur.scope_type,
        CASE aur.scope_type
            WHEN 'GLOBAL'::text THEN 0::bigint
            WHEN 'INSTITUTION'::text THEN aur.institution_id::bigint
            WHEN 'CAMPUS'::text THEN aur.campus_id::bigint
            WHEN 'DEPARTMENT'::text THEN aur.department_id::bigint
            WHEN 'PROGRAMME'::text THEN aur.programme_id::bigint
            WHEN 'SELF'::text THEN aur.user_id::bigint
            ELSE NULL::bigint
        END AS scope_entity_id,
    p.permission_id,
    p.permission_code,
    rp.permission_effect,
    'DIRECT'::text AS permission_source
   FROM v_active_user_role aur
     JOIN role_permission rp ON rp.role_id::integer = aur.role_id::integer
     JOIN permission p ON p.permission_id = rp.permission_id::bigint
  WHERE p.is_active = true
UNION ALL
 SELECT rd.delegate_user_id AS user_id,
    aur.user_role_assignment_id AS source_assignment_id,
    aur.role_id,
    aur.role_code,
    aur.scope_type,
        CASE aur.scope_type
            WHEN 'GLOBAL'::text THEN 0::bigint
            WHEN 'INSTITUTION'::text THEN aur.institution_id::bigint
            WHEN 'CAMPUS'::text THEN aur.campus_id::bigint
            WHEN 'DEPARTMENT'::text THEN aur.department_id::bigint
            WHEN 'PROGRAMME'::text THEN aur.programme_id::bigint
            WHEN 'SELF'::text THEN rd.delegate_user_id::bigint
            ELSE NULL::bigint
        END AS scope_entity_id,
    p.permission_id,
    p.permission_code,
    rp.permission_effect,
    'DELEGATED'::text AS permission_source
   FROM role_delegation rd
     JOIN v_active_user_role aur ON aur.user_role_assignment_id = rd.source_assignment_id::bigint
     JOIN role_permission rp ON rp.role_id::integer = aur.role_id::integer
     JOIN permission p ON p.permission_id = rp.permission_id::bigint
  WHERE rd.delegation_status = 'ACTIVE'::text AND rd.valid_from <= CURRENT_TIMESTAMP AND rd.valid_to > CURRENT_TIMESTAMP AND p.is_active = true;
CREATE OR REPLACE VIEW public.v_effective_user_permission WITH (security_invoker=true) AS
 SELECT user_id,
    permission_id,
    permission_code,
    scope_type,
    scope_entity_id,
        CASE
            WHEN max(is_deny) = 1 THEN 'DENY'::text
            ELSE 'ALLOW'::text
        END AS permission_effect
   FROM ( SELECT arp.user_id,
            arp.permission_id,
            arp.permission_code,
            arp.scope_type,
            arp.scope_entity_id,
                CASE
                    WHEN arp.permission_effect = 'DENY'::text THEN 1
                    ELSE 0
                END AS is_deny
           FROM v_active_role_permission arp
        UNION ALL
         SELECT upo.user_id,
            upo.permission_id,
            p.permission_code,
            upo.scope_type,
                CASE
                    WHEN upo.scope_type = ANY (ARRAY['GLOBAL'::text, 'SELF'::text]) THEN 0::bigint
                    ELSE upo.scope_entity_id::bigint
                END AS scope_entity_id,
                CASE
                    WHEN upo.permission_effect = 'DENY'::text THEN 1
                    ELSE 0
                END AS is_deny
           FROM user_permission_override upo
             JOIN permission p ON p.permission_id = upo.permission_id::bigint
          WHERE p.is_active = true AND upo.valid_from <= CURRENT_TIMESTAMP AND (upo.valid_to IS NULL OR upo.valid_to > CURRENT_TIMESTAMP)) x
  GROUP BY user_id, permission_id, permission_code, scope_type, scope_entity_id;
